/* ── NAV ── */
const nav=document.getElementById('nav');
window.addEventListener('scroll',()=>nav.classList.toggle('stuck',scrollY>60));
const burger=document.getElementById('burger'),mnav=document.getElementById('mnav');
burger.addEventListener('click',()=>{
  burger.classList.toggle('open');mnav.classList.toggle('open');
  document.body.style.overflow=mnav.classList.contains('open')?'hidden':'';
});
function closeNav(){burger.classList.remove('open');mnav.classList.remove('open');document.body.style.overflow='';}
mnav.addEventListener('click',e=>{if(e.target===mnav)closeNav();});

/* ── HERO VIDEO ── */
const heroVid=document.getElementById('heroVid'),heroStill=document.getElementById('heroStill');
heroVid.addEventListener('playing',()=>{heroStill.style.opacity='0';heroStill.style.transition='opacity 1s';});

/* ── REVEAL ── */
const obs=new IntersectionObserver(entries=>{
  entries.forEach((e,i)=>{if(e.isIntersecting)setTimeout(()=>e.target.classList.add('in'),i*70);});
},{threshold:0.08});
document.querySelectorAll('.reveal,.reveal-l,.reveal-r').forEach(el=>obs.observe(el));

/* ── STAGGERED GALLERY REVEAL ── */
const gItems = document.querySelectorAll('.g-item');
const gObs = new IntersectionObserver(entries=>{
  entries.forEach((e,i)=>{
    if(e.isIntersecting){
      setTimeout(()=>{
        e.target.style.opacity='1';
        e.target.style.transform='translateY(0) scale(1)';
      }, i*60);
      gObs.unobserve(e.target);
    }
  });
},{threshold:0.05});
gItems.forEach((el,i)=>{
  el.style.opacity='0';
  el.style.transform='translateY(20px) scale(0.98)';
  el.style.transition=`opacity .6s ease ${i*0.04}s, transform .6s ease ${i*0.04}s`;
  gObs.observe(el);
});

/* ── COUNTERS ── */
function counter(el){
  const t=parseInt(el.dataset.t);
  const sfx=el.closest('.stat').querySelector('.stat-l').textContent.includes('%')?'%':'+';
  let c=0;const step=t/120;
  const id=setInterval(()=>{c=Math.min(c+step,t);el.textContent=Math.floor(c)+sfx;if(c>=t)clearInterval(id);},16);
}
const cObs=new IntersectionObserver(entries=>{
  entries.forEach(e=>{if(e.isIntersecting){document.querySelectorAll('.stat-n').forEach(counter);cObs.disconnect();}});
},{threshold:0.5});
const statsEl=document.getElementById('stats');if(statsEl)cObs.observe(statsEl);

/* ── GALLERY FILTER ── */
function filterGallery(cat, btn) {
  document.querySelectorAll('.gf-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  gItems.forEach((el,i)=>{
    const match = cat==='all' || CATS[i]===cat;
    el.style.opacity = match ? '1' : '0.15';
    el.style.transform = match ? 'scale(1)' : 'scale(0.97)';
    el.style.pointerEvents = match ? 'auto' : 'none';
  });
}

/* ── LIGHTBOX ── */
let lbIdx=0;
function buildDots(){
  const c=document.getElementById('lbCounter');
  c.innerHTML='';
  IMGS.forEach((_,i)=>{
    const d=document.createElement('div');
    d.className='lb-dot'+(i===lbIdx?' active':'');
    d.onclick=()=>setLb(i);
    c.appendChild(d);
  });
}
function setLb(i){
  lbIdx=i;
  document.getElementById('lbImg').src=IMGS[i];
  document.getElementById('lbCapText').textContent=META[i][0]+' — '+META[i][1];
  document.getElementById('lbCapNum').textContent=(i+1)+' / '+IMGS.length;
  document.querySelectorAll('.lb-dot').forEach((d,j)=>d.classList.toggle('active',j===i));
}
function openLb(i){
  lbIdx=i;
  document.getElementById('lb').classList.add('on');
  document.body.style.overflow='hidden';
  buildDots();setLb(i);
}
function closeLb(){document.getElementById('lb').classList.remove('on');document.body.style.overflow='';}
function lbNav(d){setLb((lbIdx+d+IMGS.length)%IMGS.length);}
document.getElementById('lb').addEventListener('click',e=>{if(e.target.id==='lb')closeLb();});
document.addEventListener('keydown',e=>{
  if(e.key==='Escape')closeLb();
  if(e.key==='ArrowLeft')lbNav(-1);
  if(e.key==='ArrowRight')lbNav(1);
});

/* ── VIDEO PLAYER ── */
const mainVid=document.getElementById('mainVid');
const vidOverlay=document.getElementById('vidOverlay');
const playIcon=document.getElementById('playIcon');
const ctrlIcon=document.getElementById('ctrlIcon');
const muteIcon=document.getElementById('muteIcon');
const vcFill=document.getElementById('vcFill');
const vcTime=document.getElementById('vcTime');
function togglePlay(){
  if(mainVid.paused){mainVid.play();vidOverlay.classList.add('hidden');
    playIcon.className='fa-solid fa-pause';ctrlIcon.className='fa-solid fa-pause';
  }else{mainVid.pause();vidOverlay.classList.remove('hidden');
    playIcon.className='fa-solid fa-play';ctrlIcon.className='fa-solid fa-play';}
}
function toggleMute(){mainVid.muted=!mainVid.muted;
  muteIcon.className=mainVid.muted?'fa-solid fa-volume-xmark':'fa-solid fa-volume-high';}
function toggleFs(){
  const w=document.getElementById('vidWrap');
  if(!document.fullscreenElement)w.requestFullscreen();else document.exitFullscreen();
}
function seekVid(e){
  const r=document.getElementById('vcProgress').getBoundingClientRect();
  mainVid.currentTime=((e.clientX-r.left)/r.width)*mainVid.duration;
}
function fmtTime(s){return Math.floor(s/60)+':'+(Math.floor(s%60)+'').padStart(2,'0');}
mainVid.addEventListener('timeupdate',()=>{
  if(!mainVid.duration)return;
  vcFill.style.width=((mainVid.currentTime/mainVid.duration)*100)+'%';
  vcTime.textContent=fmtTime(mainVid.currentTime)+' / '+fmtTime(mainVid.duration);
});
mainVid.addEventListener('ended',()=>{
  vidOverlay.classList.remove('hidden');
  playIcon.className='fa-solid fa-play';ctrlIcon.className='fa-solid fa-play';
});

